source(file.path(commandArgs(TRUE)[1],'code/common.R'))
if(file.exists(file.path(out,'evidence_complete.json')))quit(save='no')
suppressPackageStartupMessages({library(SingleR);library(BiocParallel)})
x<-load_extension(root,s,FALSE);DefaultAssay(x)<-'RNA';ids<-x@misc$analysis_bin_ids;q<-LayerData(x,assay='RNA',layer='data');cts<-LayerData(x,assay='RNA',layer='counts');sym<-x[['RNA']][[]]$symbol;stopifnot(identical(colnames(q),ids));panels<-readRDS(file.path(major,'reference/marker_panels.rds'));panelmap<-rbindlist(lapply(names(panels),function(k)data.table(panel=k,symbol=panels[[k]])));panelmap[,present:=symbol%in%sym];fwrite(panelmap,file.path(out,'marker_coverage.tsv'),sep='\t');pi<-which(sym%in%unique(panelmap$symbol));md<-x[[]];groups<-list();for(tag in c('l00','l02','l08')){z<-fread(file.path(out,paste0(tag,'_clusters.tsv.gz')));stopifnot(identical(z$bin_id,ids));groups[[tag]]<-as.character(z$cluster)}
types<-fread(file.path(out,'type_metadata.tsv.gz'));stopifnot(identical(types$bin_id,ids));groups$reference_conflict<-types$reference_conflict_group
# One-hot sums match SingleR 2.12 cluster aggregation of original normalized expression.
agglog<-list();tops<-markers<-list();total_log<-rowSums(q);total_det<-rowSums(cts>0);normsum<-q;normsum@x<-expm1(normsum@x);total_norm<-rowSums(normsum)
for(tag in names(groups)){cl<-groups[[tag]];lev<-sort(unique(cl));h<-sparseMatrix(i=seq_along(ids),j=match(cl,lev),x=1,dims=c(length(ids),length(lev)));ns<-colSums(h);a<-as.matrix(q%*%h);de<-as.matrix((cts>0)%*%h);av<-as.matrix(normsum%*%h);colnames(a)<-colnames(de)<-colnames(av)<-lev;agglog[[tag]]<-a
 for(j in seq_along(lev)){n<-ns[j];pct<-de[,j]/n;ml<-a[,j]/n;po<-(total_det-de[,j])/(length(ids)-n);fc<-log2(1+av[,j]/n)-log2(1+(total_norm-av[,j])/(length(ids)-n));tab<-data.table(branch=tag,cluster=lev[j],n=n,feature_id=rownames(q),symbol=sym,mean_log=ml,pct_positive=pct,mean_normalized=av[,j]/n,log2_mean_effect=fc,delta_pct=pct-po);tops[[paste(tag,j)]]<-head(tab[pct_positive>=.1&delta_pct>=.05&log2_mean_effect>=.25][order(-log2_mean_effect,-delta_pct)],40);markers[[paste(tag,j)]]<-tab[pi] }
};fwrite(rbindlist(tops),file.path(out,'cluster_markers.tsv.gz'),sep='\t');fwrite(rbindlist(markers),file.path(out,'panel_marker_statistics.tsv.gz'),sep='\t');rm(normsum);gc()
# Aggregate only the original RNA log-expression; no BANKSY neighborhood features.
levsym<-unique(sym);G<-sparseMatrix(i=match(sym,levsym),j=seq_along(sym),x=1,dims=c(length(levsym),length(sym)));qs<-G%*%cts;rownames(qs)<-levsym;qs@x<-log1p(qs@x*rep(10000/colSums(qs),diff(qs@p)));preds<-scores<-list()
for(route in c('blca','hpca')){tr<-rebuildIndex(readRDS(file.path(prev,'reference',paste0(route,'_trained.rds'))),num.threads=8)
 for(tag in c('l02','l08')){cl<-groups[[tag]];lev<-sort(unique(cl));if(route=='blca')aa<-agglog[[tag]] else {h<-sparseMatrix(i=seq_along(ids),j=match(cl,lev),x=1,dims=c(length(ids),length(lev)));aa<-as.matrix(qs%*%h);colnames(aa)<-lev};stopifnot(all(tr$options$test.genes%in%rownames(aa)));z<-classifySingleR(aa[tr$options$test.genes,,drop=FALSE],tr,prune=FALSE,num.threads=8,BPPARAM=SerialParam());bad<-pruneScores(z);preds[[paste(route,tag)]]<-data.table(branch=tag,cluster=rownames(z),route=route,label=z$labels,pruned_label=ifelse(bad,NA,z$labels),delta_next=z$delta.next,delta_median=getDeltaFromMedian(z),n=as.integer(table(factor(cl,levels=rownames(z)))));scores[[paste(route,tag)]]<-melt(data.table(branch=tag,cluster=rownames(z),route=route,as.data.frame(z$scores)),id.vars=c('branch','cluster','route'),variable.name='candidate',value.name='initial_score') }
};fwrite(rbindlist(preds),file.path(out,'cluster_SingleR.tsv'),sep='\t');fwrite(rbindlist(scores),file.path(out,'cluster_SingleR_scores.tsv'),sep='\t')
# Export only selected original panel values for fixed ROI bins, not full expression.
rois<-fread(file.path(out,'fixed_rois.tsv'));mx<-md$x_um;my<-md$y_um;rr<-list();for(i in seq_len(nrow(rois))){b<-rois[i];ii<-which(mx>=b$x&mx<b$X&my>=b$y&my<b$Y);z<-data.table(bin_id=ids[ii],roi=b$roi);for(k in names(panels)){jj<-which(sym%in%panels[[k]]);z[[paste0('raw_',k)]]<-as.numeric(colSums(cts[jj,ii,drop=FALSE]));z[[paste0('meanlog_',k)]]<-as.numeric(colMeans(q[jj,ii,drop=FALSE]))};rr[[i]]<-z};fwrite(rbindlist(rr),file.path(out,'roi_panel_expression.tsv.gz'),sep='\t');write_json(list(section=s,n=length(ids),genes=nrow(q),marker_source='all-gene original RNA counts and LogNormalize data; all QC bins',cluster_SingleR='sum of original LogNormalize expression, equivalent to SingleR clusters interface; BLCA Ensembl; HPCA duplicate symbol counts merged then LogNormalize',references_relative='../hd_annotation_diagnosis_singler_v1/reference',marker_ranking='descriptive log2(mean normalized+1) in/out and detection difference; no P values',seed=123),file.path(out,'evidence_complete.json'),pretty=TRUE,auto_unbox=TRUE);cat('EVIDENCE_COMPLETE',s,'\n')
